	,__orig_funkin_InitState_startSong: function(songId,difficultyId) {
		if(difficultyId == null) {
			difficultyId = "normal";
		}
		var songData = funkin_data_song_SongRegistry.get_instance().fetchEntry(songId,{ variation : funkin_util_Constants.DEFAULT_VARIATION});
		if(songData == null) {
			this.startGameNormally();
			return;
		}
		switch(songId) {
		case "blammed":case "philly-nice":case "pico":
			funkin_play_PlayStatePlaylist.campaignId = "week3";
			break;
		case "2hot":case "blazin":case "darnell":case "lit-up":
			funkin_play_PlayStatePlaylist.campaignId = "weekend1";
			break;
		case "bopeebo":case "dadbattle":case "fresh":case "tutorial":
			funkin_play_PlayStatePlaylist.campaignId = "week1";
			break;
		case "high":case "milf":case "satin-panties":
			funkin_play_PlayStatePlaylist.campaignId = "week4";
			break;
		case "monster":case "south":case "spookeez":
			funkin_play_PlayStatePlaylist.campaignId = "week2";
			break;
		case "guns":case "stress":case "ugh":
			funkin_play_PlayStatePlaylist.campaignId = "week7";
			break;
		case "roses":case "senpai":case "thorns":
			funkin_play_PlayStatePlaylist.campaignId = "week6";
			break;
		case "cocoa":case "eggnog":case "winter-horrorland":
			funkin_play_PlayStatePlaylist.campaignId = "week5";
			break;
		}
		funkin_ui_transition_Transition.openPlayState({ targetSong : songData, targetDifficulty : difficultyId},{ transition : funkin_ui_transition_TransitionType.None},false);
	}
	,__orig_funkin_InitState_startLevel: function(levelId,difficultyId) {
		if(difficultyId == null) {
			difficultyId = "normal";
		}
		var currentLevel = funkin_data_story_level_LevelRegistry.get_instance().fetchEntry(levelId);
		if(currentLevel == null) {
			this.startGameNormally();
			return;
		}
		funkin_play_PlayStatePlaylist.campaignId = levelId;
		funkin_play_PlayStatePlaylist.playlistSongIds = currentLevel.getSongs();
		funkin_play_PlayStatePlaylist.isStoryMode = true;
		funkin_play_PlayStatePlaylist.campaignScore = 0;
		var targetSongId = funkin_play_PlayStatePlaylist.playlistSongIds.shift();
		var targetSong = null;
		if(targetSongId != null) {
			targetSong = funkin_data_song_SongRegistry.get_instance().fetchEntry(targetSongId,{ variation : funkin_util_Constants.DEFAULT_VARIATION});
		}
		if(targetSongId == null) {
			this.startGameNormally();
			return;
		}
		funkin_ui_transition_Transition.openPlayState({ targetSong : targetSong, targetDifficulty : difficultyId},{ transition : funkin_ui_transition_TransitionType.None},false);
	}
