funkin_assets_Assets.__orig_funkin_assets_Assets_listDataFilesInPath = function(path,suffix,blacklist,nested) {
	if(nested == null) {
		nested = false;
	}
	if(suffix == null) {
		suffix = ".json";
	}
	var queryPath = "assets/" + path;
	var textAssets = openfl_utils_Assets.list("TEXT");
	var results = [];
	var _g = 0;
	while(_g < textAssets.length) {
		var textPath = textAssets[_g];
		++_g;
		if(!StringTools.startsWith(textPath,queryPath) || !StringTools.endsWith(textPath,suffix)) {
			continue;
		}
		var pathNoPrefix = textPath.substring(queryPath.length,textPath.length - suffix.length);
		var id = nested ? pathNoPrefix.split("/")[0] : pathNoPrefix;
		if(nested && !StringTools.endsWith(textPath,"" + id + suffix)) {
			continue;
		}
		if(blacklist != null && blacklist.indexOf(id) != -1) {
			continue;
		}
		funkin_util_tools_ArrayTools.pushUnique(results,id);
	}
	return results;
};
