			while(_g < spritemaps.length) {
				var spritemap = spritemaps[_g];
				++_g;
				spritemap.json = StringTools.replace(spritemap.json,String.fromCodePoint(65279),"");
			}
			this.set_frames(animate_FlxAnimateFrames.fromAnimate(animationJson,spritemaps,settings.metadataJson,settings.cacheKey,settings.uniqueInCache,{ swfMode : settings.swfMode, cacheOnLoad : settings.cacheOnLoad, filterQuality : settings.filterQuality, onSymbolCreate : settings.onSymbolCreate}));
