var funkin_ui_freeplay_LetterSort = function(x,y) {
	this.curSelection = 2;
	this.letterHitboxes = [];
	this.letters = [];
	flixel_group_FlxTypedSpriteGroup.call(this,x,y);
	this.grpSeperators = new flixel_group_FlxTypedSpriteGroup();
	this.add(this.grpSeperators);
	this.leftArrow = new flixel_FlxSprite(-20,15).loadGraphic(funkin_assets_Paths.image("ui/freeplay/interface/mini-arrow").toFlxGraphicAsset());
	this.leftArrow.set_flipX(true);
	this.add(this.leftArrow);
	this.rightArrow = new flixel_FlxSprite(380,15).loadGraphic(funkin_assets_Paths.image("ui/freeplay/interface/mini-arrow").toFlxGraphicAsset());
	this.add(this.rightArrow);
	var _g = 0;
	while(_g < 5) {
		var i = _g++;
		var letter = new funkin_ui_freeplay_FreeplayLetter(i * 80,0,i,this.curSelection);
		letter.set_x(letter.x + 50);
		letter.set_y(letter.y + 50);
		this.add(letter);
		var letterHitbox = new flixel_FlxObject(letter.x - 50,letter.y - 50,50,50);
		letterHitbox.set_cameras(this.get_cameras());
		letterHitbox.set_active(false);
		this.letterHitboxes.push(letterHitbox);
		this.letters.push(letter);
		if(i != 2) {
			letter.scale.set_x(letter.scale.set_y(0.8));
		}
		var darkness = Math.max(Math.abs(i - 2) / 6,0.01);
		letter.set_color(flixel_util_FlxColor.getDarkened(letter.color,darkness));
		if(i == 4) {
			continue;
		}
		var sep = new flixel_FlxSprite(i * 80 + 60,20).loadGraphic(funkin_assets_Paths.image("ui/freeplay/interface/separator").toFlxGraphicAsset());
		sep.set_color(flixel_util_FlxColor.getDarkened(letter.color,darkness));
		this.grpSeperators.add(sep);
	}
	var letterHitbox = new flixel_FlxObject(0,0,1,1);
	letterHitbox.set_cameras(this.get_cameras());
	letterHitbox.set_active(false);
	this.letterHitboxes.push(letterHitbox);
	this.swipeBounds = new flixel_FlxObject(440,60,460,80);
	this.swipeBounds.set_cameras(this.get_cameras());
	this.swipeBounds.set_active(false);
	this.changeSelection(0);
};
