	,__orig_funkin_ui_freeplay_SongMenuItem_refreshDisplay: function(updateRank) {
		if(updateRank == null) {
			updateRank = true;
		}
		if(this.freeplayData == null) {
			this.songText.set_text("Random");
			this.pixelIcon.set_visible(false);
			this.ranking.set_visible(false);
			this.favIcon.set_visible(false);
			this.favIconBlurred.set_visible(false);
			this.newText.set_visible(false);
		} else {
			this.songText.set_text(this.freeplayData.get_fullSongName());
			if(this.freeplayData.get_songCharacter() != null) {
				this.pixelIcon.setCharacter(this.freeplayData.get_songCharacter());
			}
			if(this.pixelIcon.char != this.freeplayData.get_songCharacter()) {
				this.pixelIcon.set_visible(false);
			}
			var tmp = this.freeplayData.get_songStartingBpm() | 0;
			this.updateBPM(tmp != null ? tmp : 0);
			var tmp = this.freeplayData.get_difficultyRating();
			this.updateDifficultyRating(tmp != null ? tmp : 0);
			if(updateRank) {
				this.updateScoringRank(this.freeplayData.get_scoringRank());
			}
			this.newText.set_visible(this.freeplayData.get_isNew());
			this.favIcon.set_visible(this.freeplayData.get_isFav());
			this.favIconBlurred.set_visible(this.freeplayData.get_isFav());
			this.checkClip();
		}
		this.updateSelected();
	}
