	,__orig_funkin_play_components_HealthIcon_updateHealthIcon: function(health) {
		switch(this.getCurrentAnimation()) {
		case "":
			this.playAnimation("idle");
			break;
		case "fromLosing":case "fromWinning":
			if(this.isAnimationFinished()) {
				this.playAnimation("idle");
			}
			break;
		case "idle":
			if(health < funkin_play_components_HealthIcon.LOSING_THRESHOLD) {
				this.playAnimation("toLosing","losing");
			} else if(health > funkin_play_components_HealthIcon.WINNING_THRESHOLD) {
				this.playAnimation("toWinning","winning");
			} else {
				this.playAnimation("idle");
			}
			break;
		case "losing":
			if(health > funkin_play_components_HealthIcon.LOSING_THRESHOLD) {
				this.playAnimation("fromLosing","idle");
			} else {
				this.playAnimation("losing","idle");
			}
			break;
		case "toLosing":
			if(this.isAnimationFinished()) {
				this.playAnimation("losing","idle");
			}
			break;
		case "toWinning":
			if(this.isAnimationFinished()) {
				this.playAnimation("winning","idle");
			}
			break;
		case "winning":
			if(health < funkin_play_components_HealthIcon.WINNING_THRESHOLD) {
				this.playAnimation("fromWinning","idle");
			} else {
				this.playAnimation("winning","idle");
			}
			break;
		default:
			this.playAnimation("idle");
		}
	}
	,__orig_funkin_play_components_HealthIcon_loadAnimationNew: function() {
		this.animation.addByPrefix("idle","idle",24,true);
		this.animation.addByPrefix("winning","winning",24,true);
		this.animation.addByPrefix("losing","losing",24,true);
		this.animation.addByPrefix("toWinning","toWinning",24,false);
		this.animation.addByPrefix("toLosing","toLosing",24,false);
		this.animation.addByPrefix("fromWinning","fromWinning",24,false);
		this.animation.addByPrefix("fromLosing","fromLosing",24,false);
	}
	,__orig_funkin_play_components_HealthIcon_loadAnimationOld: function() {
		this.animation.add("idle",[0],0,false,false);
		this.animation.add("losing",[1],0,false,false);
		if(this.animation._sprite.get_numFrames() >= 3) {
			this.animation.add("winning",[2],0,false,false);
		}
	}
