var funkin_ui_freeplay_FreeplayRank = function(x,y) {
	this.baseY = 0;
	this.baseX = 0;
	this.rank = null;
	flixel_FlxSprite.call(this,x,y);
	this.set_frames(funkin_Paths.getSparrowAtlas("ui/freeplay/interface/freeplay-capsule/rank-badge"));
	this.animation.addByPrefix("PERFECT","PERFECT rank0",24,false);
	this.animation.addByPrefix("EXCELLENT","EXCELLENT rank0",24,false);
	this.animation.addByPrefix("GOOD","GOOD rank0",24,false);
	this.animation.addByPrefix("PERFECTSICK","PERFECT rank GOLD",24,false);
	this.animation.addByPrefix("GREAT","GREAT rank0",24,false);
	this.animation.addByPrefix("LOSS","LOSS rank0",24,false);
	this.set_blend(0);
	this.set_rank(null);
	var x = 0.9;
	var y = 0.9;
	if(y == null) {
		y = 0;
	}
	if(x == null) {
		x = 0;
	}
	this.scale.set(x,y);
	this.updateHitbox();
};
