funkin_util_ControllerName.parseName = function(name) {
	name = StringTools.replace(StringTools.replace(name.toLowerCase(),"-",""),"_","");
	if(name.indexOf("ouya") != -1) {
		return "Ouya";
	} else if(name.indexOf("wireless controller") != -1 || name.indexOf("ps4") != -1) {
		return "PS4";
	} else if(name.indexOf("logitech") != -1) {
		return "Logi";
	} else if(name.indexOf("xbox") != -1) {
		return "XBox";
	} else if(name.indexOf("xinput") != -1) {
		return "XInput";
	} else if(name.indexOf("nintendo rvlcnt01tr") != -1 || name.indexOf("nintendo rvlcnt01") != -1) {
		return "Wii";
	} else if(name.indexOf("mayflash wiimote pc adapter") != -1) {
		return "Wii";
	} else if(name.indexOf("pro controller") != -1) {
		return "Pro_Con";
	} else if(name.indexOf("joycon l+r") != -1) {
		return "Joycons";
	} else if(name.indexOf("joycon (l)") != -1) {
		return "Joycon_L";
	} else if(name.indexOf("joycon (r)") != -1) {
		return "Joycon_R";
	} else if(name.indexOf("mfi") != -1) {
		return "MFI";
	} else {
		return "Pad";
	}
};
