funkin_util_plugins_NewgroundsMedalPlugin.__orig_funkin_util_plugins_NewgroundsMedalPlugin_play = function(points,name,graphic) {
	if(name == null) {
		name = "I LOVE CUM I LOVE CUM I LOVE CUM I LOVE CUM";
	}
	if(points == null) {
		points = 100;
	}
	if(funkin_util_plugins_NewgroundsMedalPlugin.instance == null) {
		return;
	}
	var playMedal = function() {
		funkin_util_plugins_NewgroundsMedalPlugin.instance.rebuildText();
		funkin_util_plugins_NewgroundsMedalPlugin.instance.pointsLabel.set_visible(false);
		funkin_util_plugins_NewgroundsMedalPlugin.instance.nameLabel.set_visible(false);
		funkin_util_plugins_NewgroundsMedalPlugin.instance.pointsLabel.set_text(points == null ? "null" : "" + points);
		funkin_util_plugins_NewgroundsMedalPlugin.instance.nameLabel.set_text(name);
		funkin_util_plugins_NewgroundsMedalPlugin.instance.updatePositions();
		funkin_audio_FunkinSound.playOnce(funkin_Paths.sound("ui/medals/ng-fade-in"),1.0);
		funkin_util_plugins_NewgroundsMedalPlugin.instance.medal.animation.play("wholeTimeline");
		funkin_util_plugins_NewgroundsMedalPlugin.instance.medal.set_visible(true);
		if(graphic != null) {
			var cachedGraphic = funkin_assets_FunkinAssetCache.get_instance().permaCacheFlxGraphic("symbol_NGMEDAL_" + name,graphic);
			if(funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon != cachedGraphic) {
				if(funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon != null && funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon.key != null) {
					funkin_assets_FunkinBitmapFrontend.get_instance().queueToDestroy(funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon,true);
				}
				funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon = cachedGraphic;
				funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon.persist = true;
			}
		}
		funkin_util_plugins_NewgroundsMedalPlugin.instance.medal.replaceSymbolGraphic("NGMEDAL",funkin_util_plugins_NewgroundsMedalPlugin.instance.medalIcon);
	};
	if(funkin_util_plugins_NewgroundsMedalPlugin.instance.medal.isAnimationFinished() && funkin_util_plugins_NewgroundsMedalPlugin.instance.medalQueue.length == 0) {
		playMedal();
	} else {
		funkin_util_plugins_NewgroundsMedalPlugin.instance.medalQueue.push(playMedal);
	}
};
